/* @lc app=leetcode id=2612 lang=kotlin */
class Solution { fun minReverseOperations(n: Int, p: Int, banned: IntArray, k: Int): IntArray = IntArray(n) { -1 }.also { it[p] = 0 }.let { dist -> (banned.toSet() + p).let { forbid -> arrayOf(java.util.TreeSet((0 until n).filter { it % 2 == 0 && it !in forbid }), java.util.TreeSet((0 until n).filter { it % 2 != 0 && it !in forbid })) }.let { sets -> java.util.ArrayDeque<Int>().also { it.add(p) }.let { q -> generateSequence { q.poll() }.forEach { u -> (maxOf(u - k + 1, k - 1 - u)).let { L -> (minOf(u + k - 1, 2 * n - k - 1 - u)).let { R -> sets[(u + k - 1) % 2].let { s -> generateSequence { s.ceiling(L)?.takeIf { it <= R } }.forEach { v -> dist[v] = (dist[u] + 1).also { q.add(v).also { s.remove(v) } } } } } } }.run { dist } } } } }